func legalPageTitle(kind LegalPageKind) string {
	switch kind {
	case LegalPageImprint:
		return "Impressum"
	case LegalPagePrivacy:
		return "Datenschutzinformation"
	default:
		return "Cookies und Browser-Speicher"
	}
}

func legalPageIntro(kind LegalPageKind) string {
	switch kind {
	case LegalPageImprint:
		return "Anbieterinformationen und Kontaktangaben für HackWerk."
	case LegalPagePrivacy:
		return "Wie HackWerk personenbezogene Daten verarbeitet, schützt und begrenzt."
	default:
		return "Welche technisch notwendigen Cookies und lokalen Darstellungswerte HackWerk verwendet."
	}
}

func legalCurrent(actual, expected LegalPageKind) string {
	if actual == expected {
		return "page"
	}
	return ""
}

func legalHasPlaceholder(data LegalData) bool {
	values := []string{data.OperatorName, data.Address, data.Email, data.Phone, data.LegalForm, data.SupervisoryAuthority}
	return strings.Contains(strings.ToLower(strings.Join(values, " ")), "noch nicht")
}

func legalEmailURL(value string) string {
	if !strings.Contains(value, "@") || strings.Contains(strings.ToLower(value), "noch nicht") {
		return ""
	}
	return "mailto:" + value
}

func legalDuration(value time.Duration) string {
	if value <= 0 {
		return "bis zum Sitzungsende"
	}
	if value%time.Hour == 0 {
		hours := int(value / time.Hour)
		if hours == 1 {
			return "1 Stunde"
		}
		return fmt.Sprintf("%d Stunden", hours)
	}
	if value%time.Minute == 0 {
		minutes := int(value / time.Minute)
		if minutes == 1 {
			return "1 Minute"
		}
		return fmt.Sprintf("%d Minuten", minutes)
	}
	return value.String()
}

func routingPrivacyText(mode string) string {
	switch mode {
	case "osrm":
		return "konfigurierter externer Routingdienst; übertragen werden ausschließlich auf sechs Dezimalstellen begrenzte Koordinaten"
	case "osrm-internal", "osrm-tailscale":
		return "privat betriebener Routingdienst; übertragen werden ausschließlich auf sechs Dezimalstellen begrenzte Koordinaten"
	default:
		return "lokale Distanzschätzung innerhalb von HackWerk; dabei werden keine Routendaten an einen externen Dienst übertragen"
	}
}

